import json

MAX_DAYS = 14


def main(inputs):
    text = inputs["intake"].strip()
    if text.startswith("```"):
        text = text.strip("`").removeprefix("json").strip()
    facts = json.loads(text)
    asked = int(facts["days"])
    days = max(1, min(asked, MAX_DAYS))
    brief = (
        f"Destination: {facts['destination']}. From: {facts['origin']}. "
        f"Travellers: {facts['travellers']}. Wishes: {facts['wishes']}. "
        f"Length: {days} days."
    )
    notes = []
    if not facts.get("days_stated", True):
        notes.append(f"You didn't give a length, so this plans {days} days.")
    if asked > MAX_DAYS:
        notes.append(f"This plans the first {MAX_DAYS} of the {asked} days you asked for.")
    return {"brief": brief, "days": days, "note": " ".join(notes)}

import json


def main(inputs):
    text = inputs["outline"].strip()
    if text.startswith("```"):
        text = text.strip("`").removeprefix("json").strip()
    themes = json.loads(text)
    expected = int(inputs["days"])
    if len(themes) != expected:
        raise ValueError(f"The outline has {len(themes)} days, expected {expected}")
    return {
        "days": [
            {"label": f"Day {i + 1} of {expected}", "theme": theme}
            for i, theme in enumerate(themes)
        ]
    }

import json


def main(inputs):
    research = json.loads(inputs["research"])
    days = json.loads(inputs["days"])
    lines = ["## Trip plan", ""]
    if inputs["note"]:
        lines += [inputs["note"], ""]
    lines += ["### Where to go", inputs["where"], ""]
    for title, text in research.items():
        lines += [f"### {title}", text, ""]
    lines.append("### Day by day")
    for day in days:
        lines += ["", day]
    lines += ["", "*Prices and availability are estimates from general knowledge. Check them before booking.*"]
    return {"plan": "\n".join(lines)}
